type Text = { [K in keyof typeof copy.ru]: string };
type NavItem = readonly [string, string, string];

const icon = (name: string): string => {
  const paths: Record<string, string> = {
    overview: "M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z",
    review: "M5 4h10l4 4v12H5zM8 12h8M8 16h5M15 4v5h5",
    results: "M5 19V9m5 10V5m5 14v-7m5 7V3",
    tests: "M8 4h8M10 4v6l-5 8a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2l-5-8V4M8 15h8",
    tech: "M4 6h16M4 12h16M4 18h10",
    history: "M4 12a8 8 0 1 0 3-6.2M4 4v5h5",
    guide: "M12 3a7 7 0 0 0-4.7 12.2c.8.7 1.2 1.7 1.2 2.8h7c0-1.1.4-2.1 1.2-2.8A7 7 0 0 0 12 3Zm-3 18h6M10 18v3m4-3v3",
    map: "m4 6 5-2 6 2 5-2v12l-5 2-6-2-5 2zM9 4v12m6-10v12",
    git: "M7 4v9m0-9a3 3 0 1 0 0 6m0 3a3 3 0 1 0 0 6m0-6h7m0 0a3 3 0 1 0 0-6",
    settings: "M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Zm0-11v2m0 11v2m7.5-7.5h-2m-11 0h-2m12.8-5.3-1.4 1.4M7 17l-1.4 1.4m0-12.8L7 7m10 10 1.4 1.4",
    globe: "M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18Zm0-18c2.1 2.45 3.2 5.45 3.2 9S14.1 18.55 12 21m0-18C9.9 5.45 8.8 8.45 8.8 12S9.9 18.55 12 21M3.4 9h17.2M3.4 15h17.2",
    arrow: "m9 18 6-6-6-6",
    branch: "M7 4v15m0-15a3 3 0 1 0 0 6m0 9a3 3 0 1 0 0-6m0 0h10m0 0a3 3 0 1 0 0-6",
    shield: "M12 3 5 6v5c0 4.4 3 8.2 7 10 4-1.8 7-5.6 7-10V6zM9 12l2 2 4-4"
  };
  return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name] || paths.overview}"/></svg>`;
};

const action = (id: string, label: string, primary = false, iconName?: string): string =>
  `<button class="button ${primary ? "button--primary" : "button--secondary"}" data-action="${id}">${iconName ? icon(iconName) : ""}<span>${esc(label)}</span></button>`;

const sourceButton = (active: string, value: string, label: string): string =>
  `<button class="source-option ${active === value ? "is-selected" : ""}" data-action="source${value === "current-changes" ? "Current" : value === "staged" ? "Staged" : value === "compare" ? "Compare" : value === "diff-file" ? "Diff" : "GitHub"}" aria-pressed="${active === value}">${esc(label)}</button>`;

const nav = (t: Text): string => {
  const primary: NavItem[] = [["start", t.start, "overview"], ["review", t.review, "review"], ["results", t.results, "results"], ["tests", t.tests, "tests"]];
  const secondary: NavItem[] = [["architecture", t.architecture, "map"], ["git", t.git, "git"], ["guides", t.guides, "guide"], ["tech", t.tech, "tech"], ["history", t.history, "history"], ["settings", t.settings, "settings"]];
  const items = (group: readonly NavItem[]) => group.map(([id, label, iconName]) =>
    `<button role="tab" id="tab-${id}" data-tab="${id}" aria-controls="panel-${id}" aria-selected="${id === "start"}" tabindex="${id === "start" ? "0" : "-1"}">${icon(iconName)}<span>${esc(label)}</span></button>`
  ).join("");
  return `<nav class="rail-nav" role="tablist" aria-label="CodeSlicer"><div class="nav-group">${items(primary)}</div><div class="nav-divider" aria-hidden="true"></div><div class="nav-group">${items(secondary)}</div></nav>`;
};

function workspaceLabel(state: CockpitState, t: Text): string {
  const folder = state.project.workspace?.replace(/\\/gu, "/").split("/").filter(Boolean).at(-1) || t.noWorkspace;
  const branch = state.project.branch || (state.project.gitStatus === "missing" ? (t.start === "Обзор" ? "Git не подключён" : "Git not connected") : "—");
  return `<div class="workspace-line"><span>${icon("branch")}${esc(folder)}</span><b>${esc(branch)}</b></div>`;
}

function startScreen(state: CockpitState, t: Text): string {
  if (state.project.readiness === "empty") return `<section class="onboarding"><div class="onboarding__index">01</div><div><p class="eyebrow">${t.workspace}</p><h1>${t.emptyTitle}</h1><p class="lede">${t.emptyText}</p><div class="action-row">${action("openProject", t.open, true, "arrow")}${action("importGit", t.import, false, "git")}</div><button class="inline-action" data-demo-start>${icon("review")}<span>${t.guide}</span></button></div></section>`;
  if (state.project.gitStatus === "missing") return `<section class="onboarding"><div class="onboarding__index">02</div><div><p class="eyebrow">${t.workspace}</p><h1>${t.noGitTitle}</h1><p class="lede">${t.noGitText}</p><div class="action-row">${action("initGit", t.initGit, true, "git")}${action("importGit", t.import)}</div><button class="inline-action" data-demo-start>${icon("review")}<span>${t.guide}</span></button></div></section>`;
  if (["unchecked", "error", "incompatible", "not-configured"].includes(state.runtime.status)) return `<section class="onboarding"><div class="onboarding__index">03</div><div><p class="eyebrow">${t.runtime}</p><h1>${t.runtimeTitle}</h1><p class="lede">${t.runtimeText}</p><article class="runtime-readout"><span class="signal signal--warn"></span><div><strong>${esc(state.runtime.version)}</strong><small>${esc(state.runtime.diagnostic)}</small></div></article><div class="action-row">${action("refresh", t.check, true, "overview")}${action("configure", t.advanced, false, "settings")}</div><button class="inline-action" data-demo-start>${icon("review")}<span>${t.guide}</span></button></div></section>`;
  return `<section class="overview-hero"><div><p class="eyebrow">${t.localOnly} · ${t.status}</p><h1>${t.readyTitle}</h1><p class="lede">${t.readyText}</p><div class="action-row">${action("review", t.reviewChanges, true, "review")}<button class="button button--secondary" data-tab="git">${icon("git")}<span>${esc(t.openGit)}</span></button></div><div class="action-row action-row--quiet">${action("analyze", t.analyze)}${action("startServer", t.localHub)}</div></div><aside class="overview-hero__status"><div><small>${t.workspace}</small><strong>${esc(state.project.branch || "—")}</strong><span>${esc(state.project.gitMessage)}</span></div><div><small>${t.graph}</small><strong>${esc(state.project.freshness)}</strong><span>${esc(state.runtime.version)}</span></div></aside><button class="inline-action" data-demo-start>${icon("review")}<span>${t.guide}</span></button></section>`;
}

function taskCard(step: string, title: string, text: string, helper: string, actionId: string, actionLabel: string, guide: string, iconName: string, guideLabel: string): string {
  return `<article class="task-card" data-guide-anchor="${guide}"><span class="task-card__step">${esc(step)}</span><h2>${esc(title)}</h2><p>${esc(text)}</p>${helper ? `<small>${esc(helper)}</small>` : ""}<div class="task-card__actions">${action(actionId, actionLabel, actionId === "showGit", iconName)}<button class="inline-action" data-guide="${guide}">${icon("guide")}<span>${esc(guideLabel)}</span></button></div></article>`;
}

function guidesPanel(t: Text): string {
  const card = (id: string, title: string, text: string) => `<article class="guide-task" data-guide-anchor="guide-${id}"><span class="task-card__step">${esc(id.toUpperCase())}</span><h2>${esc(title)}</h2><p>${esc(text)}</p><button class="button button--secondary" data-guide="${esc(id)}">${icon("guide")}<span>${esc(t.openGuide)}</span></button></article>`;
  return `<section class="panel" id="panel-guides" role="tabpanel" aria-labelledby="tab-guides" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · ${t.guides}</p><h1>${t.guidesTitle}</h1><p class="lede">${t.guidesText}</p></header><div class="guide-grid">${card("review", t.guideReviewTitle, t.guideReviewText)}${card("git", t.guideGitTitle, t.guideGitText)}${card("tests", t.guideTestsTitle, t.guideTestsText)}${card("map", t.guideMapTitle, t.guideMapText)}</div></section>`;
}

function gitPanel(state: CockpitState, t: Text): string {
  const branches = state.gitGraph.branches.length ? state.gitGraph.branches.map(branch => `<li class="branch-row ${branch.current ? "is-current" : ""}"><span class="tree-node" aria-hidden="true"></span><div><strong>${esc(branch.name)}</strong><small>${branch.current ? t.current : t.local}${branch.upstream ? ` · ${t.tracks} ${esc(branch.upstream)}` : ""}</small></div><em>${esc(branch.tracking || "")}</em></li>`).join("") : `<p class="empty-copy">${t.noBranches}</p>`;
  const remotes = state.gitGraph.remotes.length ? state.gitGraph.remotes.map(remote => `<li class="remote-row"><strong>${esc(remote.name)}</strong><small>${esc(remote.pushUrl || remote.fetchUrl || "")}</small></li>`).join("") : `<p class="empty-copy">${t.noRemote}</p>`;
  const commits = state.gitGraph.commits.length ? `<ol class="commit-list">${state.gitGraph.commits.slice(0, 12).map(commit => `<li><code>${esc(commit.id.slice(0, 7))}</code><span>${esc(commit.subject)}</span><small>${esc(commit.refs)}</small></li>`).join("")}</ol>` : `<p class="empty-copy">${esc(state.gitGraph.message)}</p>`;
  const preflight = state.gitGraph.push ? `<article class="push-readout"><p class="eyebrow">${t.pushReady}</p><strong>${esc(state.gitGraph.push.source)} ${icon("arrow")} ${esc(state.gitGraph.push.remote)}/${esc(state.gitGraph.push.target)}</strong><dl><div><dt>AHEAD</dt><dd>${state.gitGraph.push.ahead}</dd></div><div><dt>BEHIND</dt><dd>${state.gitGraph.push.behind}</dd></div></dl><p>${esc(state.gitGraph.push.message)}</p></article>` : `<p class="empty-copy">${t.normalPush}</p>`;
  const tasks = `<section class="task-grid" aria-label="Git tasks">${taskCard("01", t.gitStepOne, t.gitStepOneText, "", "showGit", t.refreshGit, "git-status", "history", t.guide)}${taskCard("02", t.gitStepTwo, t.gitStepTwoText, t.gitFieldBranch, "createBranch", t.createBranch, "git-branch", "branch", t.guide)}${taskCard("03", t.gitStepThree, t.gitStepThreeText, "", "switchBranch", t.switchBranch, "git-switch", "git", t.guide)}${taskCard("04", t.gitStepFour, t.gitStepFourText, t.gitFieldRemote, "addRemote", t.addRemote, "git-remote", "git", t.guide)}</section>`;
  return `<section class="panel" id="panel-git" role="tabpanel" aria-labelledby="tab-git" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · GIT</p><h1>${t.gitTitle}</h1><p class="lede">${t.gitText}</p></header>${tasks}<div class="git-grid"><article class="console-card" data-guide-anchor="git-tree"><header><small>${t.local}</small><strong>${t.branches}</strong></header><ul class="branch-tree">${branches}</ul></article><article class="console-card"><header><small>${t.destination}</small><strong>${t.remotes}</strong></header><ul class="remote-list">${remotes}</ul></article></div><section class="push-workflow" data-guide-anchor="git-push"><div class="split-heading"><h2>${t.pushReady}</h2><span class="safety-note">${icon("shield")}${t.normalPush}</span></div><p class="lede">${t.gitPushText}</p>${preflight}<div class="action-row">${action("previewPush", t.previewPush, true, "review")}${action("pushBranch", t.push, false, "arrow")}<button class="inline-action" data-guide="git-push">${icon("guide")}<span>${esc(t.guide)}</span></button></div></section><h2>${t.commits}</h2><article class="console-card console-card--commits">${commits}</article></section>${guidesPanel(t)}`;
}

function statCard(label: string, value: string | number, tone = ""): string {
  return `<article class="metric ${tone}"><small>${esc(label)}</small><strong>${esc(value)}</strong></article>`;
}

export function renderCockpit(state: CockpitState, language: Language = "en"): string {
  const t = copy[language];
  const review = state.review;
  const impacts = review.impacts.map(impactCard).join("") || `<p class="empty-copy">${t.noResult}</p>`;
  const evidence = review.impacts.flatMap(item => item.evidence).slice(0, 8).map(evidenceCard).join("") || `<li class="empty-copy">${t.noResult}</li>`;
  const tests = review.tests.map((item, index) => testCard(item, index, t.run)).join("") || `<p class="empty-copy">${t.noTests}</p>`;
  const history = state.history.length ? `<ol class="history-list">${state.history.map(item => `<li><b class="risk-pill ${riskTone(item.risk)}">${esc(item.risk)}</b><span>${esc(item.source)} · ${item.affected} ${t.affected.toLowerCase()}</span><time>${esc(new Date(item.createdAt).toLocaleString(language === "ru" ? "ru-RU" : "en-US"))}</time></li>`).join("")}</ol>` : `<p class="empty-copy">${t.noHistory}</p>`;
  const runtimeLabel = state.runtime.status === "found" ? t.ready : state.runtime.status === "unchecked" ? t.notChecked : state.runtime.status;
  return `<!doctype html><html lang="${language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>${style}</style></head><body><div class="app-shell"><aside class="rail"><div class="brand"><span class="brand-mark" aria-hidden="true">S</span><span><strong>CODE SLICER</strong><small>${t.localOnly}</small></span></div>${workspaceLabel(state, t)}${nav(t)}<div class="rail-footer"><span class="signal ${state.runtime.status === "found" ? "signal--ok" : "signal--warn"}"></span><span>${esc(runtimeLabel)}</span></div></aside><main class="content"><header class="command-bar"><div><p class="eyebrow">${t.workspace}</p><strong>${esc(state.project.workspace || t.noWorkspace)}</strong></div><div class="command-bar__right"><button class="language-switch" data-language="${language === "ru" ? "en" : "ru"}" title="${language === "ru" ? "Switch to English" : "Переключить на русский"}" aria-label="${language === "ru" ? "Switch interface language to English" : "Переключить язык интерфейса на русский"}">${icon("globe")}<span>${language === "ru" ? "RU" : "EN"}</span></button>${action("refresh", t.check, false, "history")}</div></header><section class="panel panel--start" id="panel-start" role="tabpanel" aria-labelledby="tab-start">${startScreen(state, t)}</section><section class="panel" id="panel-review" role="tabpanel" aria-labelledby="tab-review" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · REVIEW</p><h1>${t.reviewReady}</h1><p class="lede">${t.localDiff}</p></header><section class="field-group"><label>${t.source}</label><div class="source-grid">${sourceButton(state.reviewSource.mode, "current-changes", t.working)}${sourceButton(state.reviewSource.mode, "staged", t.staged)}${sourceButton(state.reviewSource.mode, "compare", t.compare)}${sourceButton(state.reviewSource.mode, "diff-file", t.diff)}${sourceButton(state.reviewSource.mode, "github-pr", t.github)}</div></section><div class="base-readout"><span>${t.base}</span><strong>${esc(state.project.baseRef || state.project.baseStatus || "—")}</strong><button class="inline-action" data-action="configureBase">${t.chooseBase}${icon("arrow")}</button></div><div class="action-row">${action("review", t.runReview, true, "review")}</div></section><section class="panel" id="panel-results" role="tabpanel" aria-labelledby="tab-results" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · EVIDENCE</p><h1>${t.results}</h1><p class="lede">${language === "ru" ? t.localDiff : (review.localDiffNotice || t.localDiff)}</p></header><div class="metric-grid">${statCard(t.risk, review.riskLevel, riskTone(review.riskLevel))}${statCard(t.affected, review.impacts.length)}${statCard(t.evidence, review.impacts.reduce((count, item) => count + item.evidence.length, 0))}</div><section class="content-section"><h2>${t.why}</h2><ul class="reason-list">${review.riskReasons.length ? review.riskReasons.map(reason => `<li>${icon("arrow")}<span>${esc(reason)}</span></li>`).join("") : `<li class="empty-copy">${t.noResult}</li>`}</ul></section><section class="content-section"><h2>${t.affected}</h2><div class="stack">${impacts}</div></section><section class="content-section"><h2>${t.evidence}</h2><ul class="evidence-list">${evidence}</ul></section></section><section class="panel" id="panel-tests" role="tabpanel" aria-labelledby="tab-tests" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · TARGETED CHECKS</p><h1>${t.recommended}</h1><p class="lede">${t.noTests}</p></header><div class="stack">${tests}</div></section><section class="panel" id="panel-tech" role="tabpanel" aria-labelledby="tab-tech" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · COVERAGE</p><h1>${t.tech}</h1></header><article class="info-card"><small>${t.coverage}</small><strong>Python · TypeScript · JavaScript · Go · Java · C#</strong><span>${t.freshness}: ${esc(state.project.freshness)}</span></article><article class="info-card"><small>${t.packs}</small><strong>${t.packsText}</strong></article></section><section class="panel" id="panel-history" role="tabpanel" aria-labelledby="tab-history" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly}</p><h1>${t.recent}</h1></header>${history}</section><section class="panel" id="panel-architecture" role="tabpanel" aria-labelledby="tab-architecture" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · CANONICAL EVIDENCE GRAPH</p><h1>${t.graphTitle}</h1><p class="lede">${t.graphText}</p></header><div class="action-row">${action("showGraph", t.refreshGraph, true, "map")}${action("startServer", t.localHub, false, "arrow")}</div><article class="graph-console">${state.codeGraph.nodes.length ? `<header><span>${t.mapStatus}</span><strong>${state.codeGraph.totalNodes} ${t.nodes} · ${state.codeGraph.totalEdges} ${t.edges}</strong></header><div class="graph-nodes">${state.codeGraph.nodes.slice(0, 18).map(node => `<span title="${esc(node.kind)}"><i></i>${esc(node.label)}</span>`).join("")}</div>` : `<p class="empty-copy">${esc(state.codeGraph.message)}</p>`}</article><section class="content-section"><h2>${t.graphify}</h2><p class="lede">${t.graphifyText}</p><p class="muted">${esc(state.graphify.message)}</p><div class="action-row">${action("configureGraphify", t.connect)}${action("buildGraphify", t.build)}</div></section></section>${gitPanel(state, t)}<section class="panel" id="panel-settings" role="tabpanel" aria-labelledby="tab-settings" hidden><header class="panel-heading"><p class="eyebrow">${t.localOnly} · ${t.security}</p><h1>${t.settingsTitle}</h1></header><article class="info-card info-card--secure"><small>${t.githubTitle}</small><strong>${t.githubText}</strong><span>${esc(state.integration.githubStatus || (state.integration.githubTokenConfigured ? t.tokenSaved : ""))}</span><div class="action-row">${action("configureGitHubToken", t.addToken, false, "shield")}${action("sourceGitHub", t.oauth, false, "arrow")}</div></article><div class="action-row">${action("configure", t.advanced, false, "settings")}${action("setupSkills", t.skills)}</div><section class="guide-card"><p class="eyebrow">${t.demoLabel}</p><h2>${t.demo}</h2><p class="lede">${t.demoText}</p>${action("showDemo", t.startGuide, true, "review")}</section></section></main></div><aside id="demo-guide" class="demo-guide" role="dialog" aria-modal="false" aria-live="polite" aria-labelledby="demo-title" hidden><button class="guide-handle" data-guide-handle aria-label="${t.drag}" title="${t.drag}"><span></span><span></span><span></span><span></span><span></span><span></span></button><p>${t.demoLabel}</p><strong id="demo-title"></strong><span id="demo-text"></span><div class="action-row"><button class="button button--primary" data-demo-next>${icon("arrow")}<span>${t.next}</span></button><button class="button button--secondary" data-demo-stop>${esc(t.close)}</button></div></aside><script>${clientRouter}</script></body></html>`;
}

const style = String.raw`
:root {
  --cs-bg: #000000;
  --cs-raised: #070b08;
  --cs-panel: #0b110d;
  --cs-panel-strong: #111a13;
  --cs-line: #24402a;
  --cs-line-strong: #376b43;
  --cs-ink: #d8ffe0;
  --cs-muted: #94c79e;
  --cs-dim: #5c8b65;
  --cs-green: #4db866;
  --cs-green-bright: #72d889;
  --cs-green-deep: #123d1f;
  --cs-green-ink: #000000;
  --cs-focus: #9be8aa;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html { background: var(--cs-bg); }
body { margin: 0; min-width: 290px; background: var(--cs-bg); color: var(--cs-ink); font: 13px/1.5 var(--vscode-font-family, Inter, system-ui, sans-serif); -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
button { min-height: 36px; border: 0; font: inherit; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--cs-focus); outline-offset: 2px; }
.app-shell { min-height: 100vh; display: grid; grid-template-columns: 184px minmax(0, 1fr); background: var(--cs-bg); }
.rail { position: sticky; top: 0; height: 100vh; display: flex; flex-direction: column; padding: 16px 10px 12px; border-inline-end: 1px solid var(--cs-line); background: var(--cs-bg); }
.brand { display: flex; align-items: center; gap: 9px; padding: 4px 7px 17px; letter-spacing: .11em; }
.brand strong { display: block; font-size: 10px; font-weight: 800; }
.brand small { display: block; margin-top: 1px; color: var(--cs-dim); font-size: 9px; font-weight: 700; }
.brand-mark { display: grid; width: 28px; height: 28px; place-items: center; border: 1px solid var(--cs-green); border-radius: 9px; color: var(--cs-green); font-size: 16px; font-weight: 900; }
.workspace-line { display: grid; gap: 3px; margin: 0 4px 14px; padding: 9px; border: 1px solid var(--cs-line); border-radius: 8px; background: var(--cs-raised); }
.workspace-line span { display: flex; min-width: 0; align-items: center; gap: 5px; overflow: hidden; color: var(--cs-muted); font-size: 11px; white-space: nowrap; text-overflow: ellipsis; }
.workspace-line .icon { width: 13px; flex: 0 0 auto; color: var(--cs-green); }
.workspace-line b { overflow: hidden; color: var(--cs-ink); font-size: 11px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.rail-nav { display: grid; gap: 8px; }
.nav-group { display: grid; gap: 2px; }
.nav-divider { height: 1px; margin: 2px 5px; background: var(--cs-line); }
.rail-nav [role=tab] { display: flex; width: 100%; align-items: center; gap: 8px; padding: 8px 9px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--cs-muted); text-align: start; transition: color .15s ease, background-color .15s ease, border-color .15s ease; }
.rail-nav [role=tab]:hover { background: var(--cs-panel); color: var(--cs-ink); }
.rail-nav [role=tab][aria-selected=true] { border-color: var(--cs-green); background: var(--cs-green-deep); color: var(--cs-green); }
.rail-nav .icon { width: 16px; height: 16px; flex: 0 0 auto; stroke-width: 1.7; }
.rail-footer { display: flex; align-items: center; gap: 7px; margin-top: auto; padding: 11px 7px 3px; border-top: 1px solid var(--cs-line); color: var(--cs-muted); font-size: 11px; }
.signal { width: 7px; height: 7px; flex: 0 0 auto; border-radius: 999px; background: var(--cs-dim); }
.signal--ok { background: var(--cs-green); }
.signal--warn { background: var(--cs-green); }
.content { min-width: 0; padding: 14px; }
.command-bar { display: flex; min-height: 52px; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; padding: 8px 10px 8px 13px; border: 1px solid var(--cs-line); border-radius: 10px; background: var(--cs-raised); }
.command-bar p, .eyebrow { margin: 0; color: var(--cs-green); font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.command-bar strong { display: block; max-width: 30rem; overflow: hidden; font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
.command-bar__right, .action-row { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; }
.language-switch, .button, .source-option, .inline-action { display: inline-flex; align-items: center; justify-content: center; gap: 7px; border-radius: 7px; }
.language-switch { min-width: 52px; padding: 7px 9px; border: 1px solid var(--cs-line); background: var(--cs-raised); color: var(--cs-muted); font-size: 11px; font-weight: 800; letter-spacing: .07em; transition: color .15s ease, border-color .15s ease, background-color .15s ease; }
.language-switch:hover { border-color: var(--cs-line-strong); color: var(--cs-ink); }
.language-switch .icon, .button .icon, .inline-action .icon, .safety-note .icon { width: 15px; height: 15px; }
.button { min-height: 36px; padding: 7px 10px; border: 1px solid transparent; font-size: 12px; font-weight: 750; transition: background-color .16s ease, border-color .16s ease, color .16s ease, transform .16s cubic-bezier(.2,0,0,1); }
.button:active { transform: scale(.96); }
.button--primary { border-color: var(--cs-green); background: var(--cs-green); color: var(--cs-green-ink); }
.button--primary:hover { background: var(--cs-green-bright); }
.button--secondary { border-color: var(--cs-line-strong); background: var(--cs-raised); color: var(--cs-ink); }
.button--secondary:hover { border-color: var(--cs-green); background: var(--cs-panel-strong); }
.panel { max-width: 1100px; margin: 0 auto; padding: clamp(18px, 3vw, 30px); border: 1px solid var(--cs-line); border-radius: 12px; background: var(--cs-panel); }
.panel--start { min-height: calc(100vh - 92px); display: grid; align-items: center; }
.panel-heading { max-width: 690px; }
h1, h2, p { margin-top: 0; }
h1 { max-width: 22ch; margin-bottom: 9px; font-size: clamp(25px, 4vw, 38px); line-height: 1.11; letter-spacing: -.035em; text-wrap: balance; }
h2 { margin: 0 0 10px; font-size: 16px; line-height: 1.25; letter-spacing: -.015em; }
.lede { max-width: 66ch; margin-bottom: 0; color: var(--cs-muted); font-size: 14px; line-height: 1.55; text-wrap: pretty; }
.onboarding { display: grid; grid-template-columns: 56px minmax(0, 1fr); gap: 20px; max-width: 760px; }
.onboarding__index { display: grid; width: 46px; height: 46px; place-items: center; border: 1px solid var(--cs-green); border-radius: 8px; color: var(--cs-green); font-size: 12px; font-weight: 800; }
.onboarding .action-row, .overview-hero .action-row { margin-top: 20px; }
.action-row--quiet { margin-top: 8px !important; }
.inline-action { min-height: 30px; margin-top: 15px; padding: 3px 0; border: 0; background: transparent; color: var(--cs-green); font-size: 12px; font-weight: 700; text-align: start; }
.inline-action:hover { color: var(--cs-green-bright); text-decoration: underline; text-underline-offset: 3px; }
.runtime-readout { display: flex; align-items: flex-start; gap: 9px; margin-top: 18px; padding: 11px; border-left: 2px solid var(--cs-green); background: var(--cs-green-deep); }
.runtime-readout strong, .runtime-readout small { display: block; }
.runtime-readout small { margin-top: 2px; color: var(--cs-muted); }
.overview-hero { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(210px, .75fr); gap: 24px; align-items: start; max-width: 940px; }
.overview-hero > .inline-action { grid-column: 1 / -1; }
.overview-hero__status { display: grid; gap: 1px; border: 1px solid var(--cs-line-strong); border-radius: 10px; overflow: hidden; background: var(--cs-bg); }
.overview-hero__status div { display: grid; gap: 4px; padding: 13px; border-bottom: 1px solid var(--cs-line); }
.overview-hero__status div:last-child { border-bottom: 0; }
.overview-hero__status small, .info-card small, .console-card header small { color: var(--cs-green); font-size: 10px; font-weight: 800; letter-spacing: .1em; }
.overview-hero__status strong { font-size: 15px; }
.overview-hero__status span { color: var(--cs-muted); font-size: 11px; }
.field-group { margin-top: 25px; }
.field-group > label { display: block; margin-bottom: 8px; color: var(--cs-muted); font-size: 11px; font-weight: 700; }
.source-grid { display: flex; flex-wrap: wrap; gap: 6px; }
.source-option { min-height: 34px; padding: 6px 9px; border: 1px solid var(--cs-line); background: var(--cs-raised); color: var(--cs-muted); font-size: 12px; transition: color .15s ease, background-color .15s ease, border-color .15s ease; }
.source-option:hover { border-color: var(--cs-line-strong); color: var(--cs-ink); }
.source-option.is-selected { border-color: var(--cs-green); background: var(--cs-green-deep); color: var(--cs-green); }
.base-readout { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; margin-top: 13px; padding: 10px 0; border-bottom: 1px solid var(--cs-line); }
.base-readout > span { color: var(--cs-dim); font-size: 11px; font-weight: 700; text-transform: uppercase; }
.base-readout strong { font-size: 12px; }
.base-readout .inline-action { margin: 0 0 0 auto; }
.metric-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 24px; }
.metric { min-height: 104px; display: flex; flex-direction: column; justify-content: space-between; padding: 12px; border: 1px solid var(--cs-line); border-radius: 9px; background: var(--cs-raised); }
.metric small { color: var(--cs-muted); font-size: 10px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.metric strong { font-size: clamp(22px, 4vw, 34px); font-variant-numeric: tabular-nums; letter-spacing: -.04em; }
.metric.good strong, .metric.warn strong, .metric.danger strong { color: var(--cs-green); }
.content-section { margin-top: 28px; }.stack { display: grid; gap: 7px; }
.reason-list, .evidence-list, .history-list, .branch-tree, .remote-list, .commit-list { margin: 0; padding: 0; list-style: none; }
.reason-list { display: grid; gap: 7px; }.reason-list li { display: flex; gap: 8px; align-items: flex-start; color: var(--cs-muted); }.reason-list .icon { width: 14px; height: 14px; flex: 0 0 auto; margin-top: 3px; color: var(--cs-green); }
.empty-copy, .muted { color: var(--cs-muted); }.empty-copy { margin: 0; padding: 15px 0; }
.info-card, .graph-console, .console-card, .push-readout, .guide-card { margin-top: 14px; padding: 14px; border: 1px solid var(--cs-line); border-radius: 9px; background: var(--cs-raised); }
.info-card { display: grid; gap: 7px; }.info-card strong { max-width: 73ch; font-size: 13px; line-height: 1.45; }.info-card span { color: var(--cs-muted); font-size: 12px; }.info-card--secure { border-color: var(--cs-green); }
.result-card, .test-card { width: 100%; display: grid; gap: 4px; padding: 12px; border: 1px solid var(--cs-line); border-radius: 8px; background: var(--cs-raised); color: var(--cs-ink); text-align: start; }
.impact-card { position: relative; transition: border-color .16s ease, background-color .16s ease, transform .16s cubic-bezier(.2,0,0,1); }
.impact-card:hover { border-color: var(--cs-green); background: var(--cs-panel-strong); }.impact-card:active { transform: scale(.96); }
.result-card__kind { color: var(--cs-green); font-size: 9px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }.result-card strong { font-size: 13px; }.result-card__reason { color: var(--cs-muted); font-size: 12px; }.result-card small, .test-card small { color: var(--cs-dim); font-family: var(--vscode-editor-font-family, ui-monospace, monospace); font-size: 10px; overflow-wrap: anywhere; }
.test-card { grid-template-columns: minmax(0, 1fr) auto; align-items: center; }.test-card > div { display: grid; gap: 4px; min-width: 0; }.test-card strong { overflow: hidden; font-size: 13px; text-overflow: ellipsis; white-space: nowrap; }.test-card p { margin: 0; color: var(--cs-muted); font-size: 12px; }.test-card .button { align-self: center; }
.evidence-list { display: grid; gap: 6px; }.evidence-list li { display: grid; gap: 3px; padding: 9px 10px; border-left: 2px solid var(--cs-line-strong); background: var(--cs-raised); color: var(--cs-muted); font-family: var(--vscode-editor-font-family, ui-monospace, SFMono-Regular, Menlo, monospace); font-size: 11px; overflow-wrap: anywhere; }.evidence-list strong { color: var(--cs-ink); font-size: 11px; }.evidence-list em { color: var(--cs-green); font-style: normal; }
.history-list { display: grid; }.history-list li { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 11px; align-items: center; padding: 12px 0; border-bottom: 1px solid var(--cs-line); }.history-list span, .history-list time { min-width: 0; color: var(--cs-muted); font-size: 12px; }.history-list time { text-align: end; font-variant-numeric: tabular-nums; }
.risk-pill { padding: 3px 6px; border-radius: 4px; background: var(--cs-panel-strong); color: var(--cs-green); font-size: 10px; letter-spacing: .06em; }.risk-pill.good, .risk-pill.warn, .risk-pill.danger { color: var(--cs-green); }
.graph-console { min-height: 176px; background: var(--cs-raised); }.graph-console header { display: flex; align-items: center; justify-content: space-between; gap: 9px; margin-bottom: 18px; font-size: 11px; }.graph-console header span { color: var(--cs-green); font-size: 10px; font-weight: 800; letter-spacing: .1em; }.graph-nodes { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; }.graph-nodes span { display: inline-flex; align-items: center; gap: 5px; max-width: 100%; padding: 5px 7px; border: 1px solid var(--cs-line-strong); border-radius: 999px; background: var(--cs-panel-strong); color: var(--cs-ink); font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.graph-nodes i { width: 5px; height: 5px; flex: 0 0 auto; border-radius: 99px; background: var(--cs-green); }
.git-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; margin-top: 23px; }.console-card { margin-top: 0; }.console-card header { display: grid; gap: 1px; padding-bottom: 10px; border-bottom: 1px solid var(--cs-line); }.console-card header strong { font-size: 14px; }.branch-tree { margin: 8px 0 0 7px; padding-left: 13px; border-left: 1px solid var(--cs-line-strong); }.branch-row { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; padding: 8px 0; }.branch-row .tree-node { position: absolute; inset: 17px auto auto -14px; width: 10px; border-top: 1px solid var(--cs-line-strong); }.branch-row strong, .branch-row small { display: block; }.branch-row strong { overflow: hidden; font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }.branch-row small, .branch-row em { color: var(--cs-muted); font-size: 10px; font-style: normal; }.branch-row em { align-self: center; text-align: end; }.branch-row.is-current strong { color: var(--cs-green); }.remote-list { display: grid; gap: 1px; margin-top: 8px; }.remote-row { display: grid; gap: 3px; padding: 8px 0; border-bottom: 1px solid var(--cs-line); }.remote-row:last-child { border-bottom: 0; }.remote-row strong { font-size: 12px; }.remote-row small { color: var(--cs-muted); font-size: 10px; overflow-wrap: anywhere; }
.split-heading { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; margin-top: 28px; }.split-heading h2 { margin: 0; }.safety-note { display: inline-flex; gap: 5px; align-items: center; max-width: 30ch; color: var(--cs-muted); font-size: 10px; text-align: end; }.safety-note .icon { color: var(--cs-green); }.push-readout { border-color: var(--cs-green); }.push-readout .eyebrow { margin-bottom: 8px; }.push-readout > strong { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; font-size: 14px; }.push-readout > strong .icon { width: 15px; color: var(--cs-green); }.push-readout dl { display: flex; gap: 22px; margin: 14px 0 8px; }.push-readout dl div { display: grid; gap: 0; }.push-readout dt { color: var(--cs-dim); font-size: 9px; font-weight: 800; letter-spacing: .1em; }.push-readout dd { margin: 0; color: var(--cs-ink); font-size: 20px; font-variant-numeric: tabular-nums; }.push-readout p:last-child { margin-bottom: 0; color: var(--cs-muted); font-size: 12px; }.console-card--commits { overflow: auto; }.commit-list { min-width: 390px; }.commit-list li { display: grid; grid-template-columns: 62px minmax(0, 1fr) auto; gap: 9px; align-items: center; padding: 8px 0; border-bottom: 1px solid var(--cs-line); }.commit-list li:last-child { border-bottom: 0; }.commit-list code { color: var(--cs-green); font-family: var(--vscode-editor-font-family, ui-monospace, monospace); font-size: 11px; }.commit-list span { overflow: hidden; font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }.commit-list small { color: var(--cs-muted); font-size: 10px; text-align: end; }
.guide-card { margin-top: 30px; border-top-color: var(--cs-green); }.guide-card h2 { margin-top: 6px; }.guide-card .button { margin-top: 9px; }
.task-grid, .guide-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 26px; }.task-card, .guide-task { display: grid; align-content: start; gap: 8px; min-height: 215px; padding: 16px; border: 1px solid var(--cs-line); border-radius: 10px; background: var(--cs-raised); }.task-card__step { color: var(--cs-green); font-size: 10px; font-weight: 800; letter-spacing: .12em; }.task-card h2, .guide-task h2 { margin: 0; font-size: 16px; }.task-card p, .guide-task p { margin: 0; color: var(--cs-muted); font-size: 12px; line-height: 1.55; }.task-card small { min-height: 28px; color: var(--cs-dim); font-size: 11px; line-height: 1.45; }.task-card__actions { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; margin-top: auto; }.task-card__actions .inline-action { margin: 0; }.guide-task .button { justify-self: start; margin-top: auto; }.push-workflow { margin-top: 26px; padding: 16px; border: 1px solid var(--cs-line); border-radius: 10px; background: var(--cs-raised); }.push-workflow .lede { margin-bottom: 15px; }.guide-target { position: relative; z-index: 1; outline: 2px solid var(--cs-green-bright); outline-offset: 4px; border-color: var(--cs-green-bright) !important; }.guide-target::after { position: absolute; inset: -7px; z-index: -1; border: 1px solid var(--cs-green); border-radius: inherit; content: ""; pointer-events: none; }
.demo-guide { position: fixed; right: 20px; bottom: 20px; z-index: 20; width: min(350px, calc(100vw - 32px)); padding: 17px; border: 1px solid var(--cs-green); border-radius: 11px; background: var(--cs-bg); color: var(--cs-ink); }.demo-guide > p { margin: 7px 0 5px; color: var(--cs-green); font-size: 10px; font-weight: 800; letter-spacing: .1em; }.demo-guide > strong { display: block; font-size: 16px; letter-spacing: -.02em; }.demo-guide > span { display: block; margin: 6px 0 13px; color: var(--cs-muted); line-height: 1.5; }.demo-guide .action-row { justify-content: flex-end; }.guide-handle { display: grid; grid-template-columns: repeat(3, 3px); gap: 3px; width: 28px; min-height: 26px; padding: 5px; border: 0; border-radius: 5px; background: transparent; cursor: grab; }.guide-handle:active { cursor: grabbing; }.guide-handle span { width: 3px; height: 3px; border-radius: 50%; background: var(--cs-dim); }.guide-handle:hover span { background: var(--cs-green); }
@media (max-width: 720px) { .app-shell { display: block; }.rail { position: relative; height: auto; padding: 10px; border-inline-end: 0; border-bottom: 1px solid var(--cs-line); }.brand { display: none; }.workspace-line { display: none; }.rail-nav { display: flex; overflow-x: auto; gap: 5px; padding-bottom: 1px; }.nav-group { display: flex; gap: 3px; }.nav-divider { width: 1px; height: 24px; margin: 3px 2px; }.rail-nav [role=tab] { width: auto; min-width: 34px; padding: 7px; }.rail-nav [role=tab] span { display: none; }.rail-footer { display: none; }.content { padding: 9px; }.command-bar { padding: 8px; }.command-bar strong { max-width: 14rem; }.overview-hero, .git-grid, .task-grid, .guide-grid { grid-template-columns: 1fr; }.overview-hero > .inline-action { grid-column: auto; }.metric-grid { gap: 6px; }.metric { min-height: 82px; padding: 9px; }.metric strong { font-size: 23px; }.test-card { grid-template-columns: 1fr; }.test-card .button { justify-self: start; }.history-list li { grid-template-columns: auto minmax(0, 1fr); }.history-list time { grid-column: 2; text-align: start; }.split-heading { align-items: flex-start; flex-direction: column; }.safety-note { text-align: start; }.demo-guide { right: 12px; bottom: 12px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; } }
`;
